  "code": "private CloseableHttpResponse getHttpResponse(BaseMessage message) throws Exception {
    HttpRequestBase request;
    if (message instanceof CustomWebhookMessage) {
        CustomWebhookMessage webhook = (CustomWebhookMessage) message;
        request = constructHttpRequest(webhook.getMethod());
        request.setURI(buildUri(webhook.getScheme(), webhook.getHost(), webhook.getPort(),
                webhook.getPath(), webhook.getQueryParams()));

        Map<String, String> headers = webhook.getHeaderParams();
        if (headers == null || headers.isEmpty()) {
            request.setHeader("Content-Type", "application/json");
        } else {
            for (Map.Entry<String, String> header : headers.entrySet()) {
                request.addHeader(header.getKey(), header.getValue());
            }
        }
    } else {
        request = new HttpPost(message.getUrl());
    }

    if (request instanceof HttpEntityEnclosingRequest) {
        HttpEntityEnclosingRequest entityRequest = (HttpEntityEnclosingRequest) request;
        entityRequest.setEntity(new StringEntity(extractBody(message), StandardCharsets.UTF_8));
    }

    return HTTP_CLIENT.execute(request);
}",
  "imports": "import java.nio.charset.StandardCharsets;
import java.util.Map;
import org.apache.http.HttpEntityEnclosingRequest;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.client.methods.HttpRequestBase;
import org.apache.http.entity.StringEntity;",
  "dependency_notes": "The method assumes buildUri accepts the scheme, host, port, path, and query parameter getter values in that order and returns a URI. constructHttpRequest must accept the type returned by getMethod() and return an HttpRequestBase. extractBody must return a non-null String for entity-capable requests. getHeaderParams() must return a Map<String, String> or null, and getUrl() must return a String or URI accepted by HttpPost. HTTP_CLIENT must expose an execute overload that accepts the request and returns CloseableHttpResponse. BaseMessage and CustomWebhookMessage are assumed to be in scope. The caller is responsible for closing the returned response.",
  "retrieval_notes": "Used only the supplied specification."
